namespace {

using Clock = std::chrono::steady_clock;
using Fields = std::vector<std::pair<std::string, std::string>>;

std::string quote(const std::string& input) {
    std::ostringstream out;
    out << '"';
    for (const unsigned char value : input) {
        switch (value) {
        case '"':
            out << "\\\"";
            break;
        case '\\':
            out << "\\\\";
            break;
        case '\b':
            out << "\\b";
            break;
        case '\f':
            out << "\\f";
            break;
        case '\n':
            out << "\\n";
            break;
        case '\r':
            out << "\\r";
            break;
        case '\t':
            out << "\\t";
            break;
        default:
            if (value < 0x20) {
                out << "\\u" << std::hex << std::setw(4) << std::setfill('0')
                    << static_cast<int>(value) << std::dec;
            } else {
                out << value;
            }
        }
    }
    out << '"';
    return out.str();
}

std::string number(double value) {
    if (!std::isfinite(value)) {
        throw std::runtime_error("non-finite numerical result");
    }
    std::ostringstream out;
    out << std::setprecision(17) << value;
    return out.str();
}

std::string number(const std::optional<double>& value) {
    return value ? number(*value) : "null";
}

std::string object(const Fields& fields) {
    std::string out = "{";
    for (const auto& field : fields) {
        if (out.size() > 1) {
            out += ',';
        }
        out += quote(field.first) + ':' + field.second;
    }
    return out + '}';
}

std::string array(const std::vector<std::string>& values) {
    std::string out = "[";
    for (const auto& value : values) {
        if (out.size() > 1) {
            out += ',';
        }
        out += value;
    }
    return out + ']';
}

std::string strings(const std::vector<std::string>& values) {
    std::vector<std::string> encoded;
    for (const auto& value : values) {
        encoded.push_back(quote(value));
    }
    return array(encoded);
}

std::string support(const phasegrid::CompletionSupport& value) {
    return object({{"weighted_fraction", number(value.weighted_fraction)},
            {"expected_background_fraction", number(value.expected_background_fraction)},
            {"normalized_support", number(value.normalized_support)},
            {"significance", number(value.significance)},
            {"effective_events", number(value.effective_events)},
            {"grid_occupancy", number(value.grid_occupancy)},
            {"supported_beats", std::to_string(value.supported_beats)}});
}

std::string beats(double bpm, double phase, double duration) {
    const double period = 60 / bpm;
    std::vector<std::string> values;
    for (std::size_t index = 0; index < 1000000; ++index) {
        const double time = phase + index * period;
        if (time >= duration) {
            return array(values);
        }
        if (time >= 0) {
            values.push_back(number(time));
        }
    }
    throw std::runtime_error("constant diagnostic grid exceeds beat budget");
}

struct Options {
    std::string pcm;
    std::string output;
    std::string frontend = "rms";
    std::string profile = "reference";
    double sample_rate = 0;
    std::size_t channels = 2;
};

void parse(int argc, char** argv, Options* pResult) {
    auto& result = *pResult;
    for (int index = 1; index < argc; ++index) {
        const std::string key = argv[index];
        if (key == "--help") {
            std::cout << "Usage: phasegrid_completion_probe --pcm FILE "
                         "--sample-rate HZ "
                         "--channels 2 --frontend rms|multiband --profile "
                         "reference|completion|completion-strict "
                         "--output FILE\nInput is little-endian interleaved "
                         "float32 PCM.\n";
            std::exit(0);
        }
        if (index + 1 == argc) {
            throw std::invalid_argument("missing value for " + key);
        }
        const std::string value = argv[++index];
        if (key == "--pcm") {
            result.pcm = value;
        } else if (key == "--output") {
            result.output = value;
        } else if (key == "--frontend") {
            result.frontend = value;
        } else if (key == "--profile") {
            result.profile = value;
        } else if (key == "--sample-rate" || key == "--channels") {
            std::size_t consumed = 0;
            const double parsed = std::stod(value, &consumed);
            if (consumed != value.size() || !std::isfinite(parsed)) {
                throw std::invalid_argument("invalid number for " + key);
            }
            if (key == "--sample-rate") {
                result.sample_rate = parsed;
            } else if (parsed == 2) {
                result.channels = 2;
            } else {
                throw std::invalid_argument("probe requires native stereo PCM (--channels 2)");
            }
        } else {
            throw std::invalid_argument("unknown option " + key);
        }
    }
    if (result.pcm.empty() || result.output.empty() || result.sample_rate < 1000 ||
            result.sample_rate > 384000 ||
            (result.frontend != "rms" && result.frontend != "multiband") ||
            (result.profile != "reference" && result.profile != "completion" &&
                    result.profile != "completion-strict")) {
        throw std::invalid_argument("invalid or incomplete options; use --help");
    }
}

template<typename Detector>
std::vector<phasegrid::Transient> detect(
        const Options& options, std::uint64_t* frames, double* frontend_ms, double* read_ms) {
    std::ifstream stream(options.pcm, std::ios::binary);
    if (!stream) {
        throw std::runtime_error("cannot open PCM input");
    }
    const auto reset_start = Clock::now();
    typename Detector::Config config;
    config.sample_rate = options.sample_rate;
    config.channels = options.channels;
    Detector detector(config);
    *frontend_ms = std::chrono::duration<double, std::milli>(Clock::now() - reset_start).count();
    if (!detector.last_error().empty()) {
        throw std::runtime_error(detector.last_error());
    }
    constexpr std::size_t kChunkFrames = 8192;
    std::vector<float> pcm(kChunkFrames * options.channels);
    const std::uint16_t byte_order = 1;
    const bool little_endian = *reinterpret_cast<const unsigned char*>(&byte_order) == 1;
    while (true) {
        const auto read_start = Clock::now();
        stream.read(reinterpret_cast<char*>(pcm.data()),
                static_cast<std::streamsize>(pcm.size() * sizeof(float)));
        const auto count = stream.gcount();
        *read_ms += std::chrono::duration<double, std::milli>(Clock::now() - read_start).count();
        if (count % (sizeof(float) * options.channels)) {
            throw std::runtime_error("PCM ends in an incomplete stereo float32 frame");
        }
        if (!stream.eof() && !stream) {
            throw std::runtime_error("PCM read failed");
        }
        if (!count) {
            break;
        }
        if (!little_endian) {
            auto* bytes = reinterpret_cast<unsigned char*>(pcm.data());
            for (std::streamsize index = 0; index < count; index += 4) {
                std::swap(bytes[index], bytes[index + 3]);
                std::swap(bytes[index + 1], bytes[index + 2]);
            }
        }
        const auto process_start = Clock::now();
        const bool processed = detector.process(pcm.data(), count / sizeof(float));
        *frontend_ms +=
                std::chrono::duration<double, std::milli>(Clock::now() - process_start).count();
        if (!processed) {
            throw std::runtime_error(detector.last_error());
        }
    }
    const auto finalize_start = Clock::now();
    const bool finalized = detector.finalize();
    *frontend_ms +=
            std::chrono::duration<double, std::milli>(Clock::now() - finalize_start).count();
    if (!finalized) {
        throw std::runtime_error(detector.last_error());
    }
    *frames = detector.frames_processed();
    return detector.transients();
}

Fields reference(const std::vector<phasegrid::Transient>& events, double duration) {
    phasegrid::PipelineConfig config;
    config.search_plan = phasegrid::decompiled_radius_one_plan();
    auto policies = phasegrid::proposed_count_only_policies();
    std::vector<std::string> local_evidence;
    std::vector<double> proposals;
    const auto original_selector = policies.local_selector;
    policies.local_selector =
            [&](const phasegrid::LocalWindow& window, double minimum, double maximum) {
                const auto proposal = original_selector(window, minimum, maximum);
                local_evidence.push_back(object({{"start_seconds", number(window.start_seconds)},
                        {"end_seconds", number(window.end_seconds)},
                        {"bpm", number(proposal)},
                        {"interval_groups", std::to_string(window.groups.size())}}));
                if (proposal) {
                    proposals.push_back(*proposal);
                }
                return proposal;
            };
    const auto result = phasegrid::analyze_transients(events, duration, config, policies);
    const bool accepted = result.status == phasegrid::AnalysisStatus::Candidate;
    std::optional<phasegrid::RefinedTempo> refined = result.refinement;
    const auto winner = phasegrid::strongest_tempo(phasegrid::tempo_consensus(proposals));
    if (!refined && winner) {
        const auto seed = policies.octave_selector(
                winner->mean_bpm, events, config.minimum_bpm, config.maximum_bpm);
        if (seed) {
            refined = phasegrid::refine_tempo(events, *seed, config.search_plan);
        }
    }
    std::optional<double> bpm = result.bpm;
    std::optional<double> phase = result.beat_phase_seconds;
    std::optional<double> raw_phase;
    std::optional<double> peak_fraction;
    std::size_t correction_support = result.phase_support;
    std::vector<std::string> candidates;
    if (refined) {
        bpm = refined->bpm;
        raw_phase = policies.coarse_phase_selector(*refined, events);
        if (raw_phase) {
            const auto corrected = phasegrid::correct_phase(
                    events, *bpm, *raw_phase, phasegrid::PhaseWrapPolicy::CanonicalBeatPhase);
            phase = corrected.phase_seconds;
            correction_support = corrected.support_count;
        }
        const auto& histogram = refined->stages.back().histogram;
        if (histogram.total_weight > 0) {
            peak_fraction = *std::max_element(histogram.bins.begin(), histogram.bins.end()) /
                    histogram.total_weight;
        }
        candidates.push_back(object({{"seed_bpm", winner ? number(winner->mean_bpm) : "null"},
                {"bpm", number(bpm)},
                {"raw_phase_seconds", number(raw_phase)},
                {"beat_phase_seconds", number(phase)},
                {"peak_fraction", number(peak_fraction)},
                {"accepted", accepted ? "true" : "false"},
                {"correction_support", std::to_string(correction_support)}}));
    }
    std::string status = accepted ? "accepted" : (refined ? "rejected" : "nocandidate");
    return {{"status", quote(status)},
            {"accepted", accepted ? "true" : "false"},
            {"bpm", number(bpm)},
            {"beat_phase_seconds", number(phase)},
            {"raw_phase_seconds", number(raw_phase)},
            {"recovered_coarse_phase_seconds", number(raw_phase)},
            {"peak_fraction", number(peak_fraction)},
            {"local_windows", std::to_string(result.local_windows)},
            {"local_votes", std::to_string(result.local_votes)},
            {"local_evidence", array(local_evidence)},
            {"candidates", array(candidates)},
            {"diagnostics", strings(result.diagnostics)},
            {"beat_times_seconds", accepted && bpm && phase ? beats(*bpm, *phase, duration) : "[]"},
            {"diagnostic_beat_times_seconds", bpm && phase ? beats(*bpm, *phase, duration) : "[]"},
            {"diagnostic_phase_scope",
                    quote("refinement/coarse/corrected phase retained even "
                          "when reference concentration guard rejects; "
                          "rejected diagnostic beats are never published")}};
}

Fields completion(const std::vector<phasegrid::Transient>& events, double duration, bool strict) {
    phasegrid::CompletionConfig config;
    config.acceptance_mode = strict ? phasegrid::AcceptanceMode::StrictConstant
                                    : phasegrid::AcceptanceMode::BestFitConstant;
    const auto result = phasegrid::complete_analysis(events, duration, config);
    const bool accepted = result.status == phasegrid::CompletionStatus::Accepted;
    std::vector<std::string> local_evidence;
    for (const auto& value : result.local_evidence) {
        local_evidence.push_back(object({{"start_seconds", number(value.start_seconds)},
                {"end_seconds", number(value.end_seconds)},
                {"bpm", number(value.bpm)},
                {"phase_seconds", number(value.phase_seconds)},
                {"vote_weight", number(value.vote_weight)},
                {"support", support(value.support)}}));
    }
    std::vector<std::string> candidates;
    for (const auto& value : result.candidates) {
        candidates.push_back(object({{"seed_bpm", number(value.seed_bpm)},
                {"bpm", number(value.bpm)},
                {"raw_phase_seconds", number(value.raw_phase_seconds)},
                {"recovered_corrected_phase_seconds",
                        number(value.recovered_corrected_phase_seconds)},
                {"beat_phase_seconds", number(value.beat_phase_seconds)},
                {"phase_correction_retained", value.phase_correction_retained ? "true" : "false"},
                {"local_vote_weight", number(value.local_vote_weight)},
                {"support", support(value.support)},
                {"evaluated_sections", std::to_string(value.evaluated_sections)},
                {"supported_sections", std::to_string(value.supported_sections)},
                {"supported_section_fraction", number(value.supported_section_fraction)},
                {"phase_retention", number(value.phase_retention)},
                {"conflicting_sections", std::to_string(value.conflicting_sections)},
                {"longest_conflict_run", std::to_string(value.longest_conflict_run)},
                {"score", number(value.score)},
                {"accepted", value.accepted ? "true" : "false"},
                {"constant_supported", value.constant_supported ? "true" : "false"},
                {"best_fit_estimate", value.best_fit_estimate ? "true" : "false"},
                {"rhythmic_coverage", number(value.rhythmic_coverage)},
                {"rejection_reasons", strings(value.rejection_reasons)}}));
    }
    const auto bpm = result.bpm;
    const auto phase = result.beat_phase_seconds;
    return {{"status",
                    quote(accepted ? "accepted"
                                   : (result.status == phasegrid::CompletionStatus::Rejected
                                                     ? "rejected"
                                                     : "nocandidate"))},
            {"accepted", accepted ? "true" : "false"},
            {"acceptance_mode", quote(strict ? "StrictConstant" : "BestFitConstant")},
            {"constant_supported", result.constant_supported ? "true" : "false"},
            {"best_fit_estimate", result.best_fit_estimate ? "true" : "false"},
            {"rhythmic_coverage", number(result.rhythmic_coverage)},
            {"bpm", number(bpm)},
            {"beat_phase_seconds", number(phase)},
            {"raw_phase_seconds", number(result.raw_phase_seconds)},
            {"recovered_coarse_phase_seconds", number(result.recovered_coarse_phase_seconds)},
            {"recovered_corrected_phase_seconds", number(result.recovered_corrected_phase_seconds)},
            {"support", support(result.support)},
            {"local_windows", std::to_string(result.local_windows)},
            {"local_evidence", array(local_evidence)},
            {"candidates", array(candidates)},
            {"diagnostics", strings(result.diagnostics)},
            {"beat_times_seconds", accepted && bpm && phase ? beats(*bpm, *phase, duration) : "[]"},
            {"diagnostic_beat_times_seconds", bpm && phase ? beats(*bpm, *phase, duration) : "[]"},
            {"diagnostic_phase_scope",
                    quote("best proposed completion candidate; rejected "
                          "diagnostic beats are never published")}};
}

void write(const std::string& path, const std::string& json) {
    if (path.empty() || path == "-") {
        std::cout << json << '\n';
        return;
    }
    std::ofstream output(path);
    if (!output || !(output << json << '\n')) {
        throw std::runtime_error("cannot write JSON output");
    }
}

} // namespace

int main(int argc, char** argv) {
    Options options;
    try {
        parse(argc, argv, &options);
        static_assert(sizeof(float) == 4 && std::numeric_limits<float>::is_iec559,
                "probe requires IEEE float32");
        std::uint64_t frames = 0;
        double frontend_ms = 0;
        double read_ms = 0;
        const auto events = options.frontend == "rms"
                ? detect<phasegrid::TransientDetector>(options, &frames, &frontend_ms, &read_ms)
                : detect<phasegrid::MultibandDetector>(options, &frames, &frontend_ms, &read_ms);
        const double duration = static_cast<double>(frames) / options.sample_rate;
        if (!(duration > 0)) {
            throw std::runtime_error("empty PCM input");
        }
        const auto core_start = Clock::now();
        Fields fields = options.profile == "reference"
                ? reference(events, duration)
                : completion(events, duration, options.profile == "completion-strict");
        const double core_ms =
                std::chrono::duration<double, std::milli>(Clock::now() - core_start).count();
        fields.insert(fields.end(),
                {{"schema_version", "1"},
                        {"frontend", quote(options.frontend)},
                        {"profile", quote(options.profile)},
                        {"pcm_path", quote(options.pcm)},
                        {"sample_rate", number(options.sample_rate)},
                        {"channels", std::to_string(options.channels)},
                        {"decoded_frames", std::to_string(frames)},
                        {"duration_seconds", number(duration)},
                        {"events", std::to_string(events.size())},
                        {"frontend_ms", number(frontend_ms)},
                        {"core_ms", number(core_ms)},
                        {"pcm_read_ms", number(read_ms)},
                        {"analysis_ms", number(frontend_ms + core_ms)},
                        {"timing_scope",
                                quote("front-end reset/process/finalize; core "
                                      "analysis plus "
                                      "diagnostic construction; PCM read timed "
                                      "separately; "
                                      "final JSON serialization and output "
                                      "excluded")},
                        {"experimental", "true"},
                        {"original_equivalence", "false"}});
        write(options.output, object(fields));
        return 0;
    } catch (const std::exception& error) {
        const auto json = object({{"status", quote("error")},
                {"accepted", "false"},
                {"error", quote(error.what())},
                {"frontend", quote(options.frontend)},
                {"profile", quote(options.profile)}});
        try {
            write(options.output, json);
        } catch (const std::exception&) {
            std::cerr << json << '\n';
        }
        return 2;
    }
}
